import io
import base64
import numpy as np
from PIL import Image
from shiny import App, ui, render, reactive

# ==============================================================================
# LÓGICA MATEMÁTICA PURA (NUMPY & PILLOW - CERO OPENCV / CERO MATPLOTLIB)
# ==============================================================================

def generate_test_image(preset: str) -> np.ndarray:
    """Genera imágenes sintéticas didácticas de 256x256 píxeles."""
    x = np.linspace(-3, 3, 256)
    y = np.linspace(-3, 3, 256)
    xx, yy = np.meshgrid(x, y)
    pattern = (np.sin(xx**2 + yy**2) * 127 + 128).astype(np.float32)

    if preset == "fog":
        # Bajo contraste: comprimido en el rango medio gris (110 - 145)
        img = 110 + (pattern / 255.0) * 35
    elif preset == "dark":
        # Subexpuesta: concentrado en sombras (5 - 65)
        img = 5 + (pattern / 255.0) * 60
    else:
        # Normal con sombras y luces
        img = pattern

    return np.clip(img, 0, 255).astype(np.uint8)

def equalize_histogram(img: np.ndarray, strength: float = 1.0) -> np.ndarray:
    """Ecualización por Función Acumulada de Distribución (CDF) en NumPy."""
    hist = np.bincount(img.flatten(), minlength=256)
    cdf = hist.cumsum().astype(np.float32)
    cdf_mask = np.ma.masked_equal(cdf, 0)

    # Normalización lineal del CDF al rango [0, 255]
    cdf_norm = (cdf_mask - cdf_mask.min()) * 255 / (cdf_mask.max() - cdf_mask.min())
    lookup = np.ma.filled(cdf_norm, 0).astype(np.uint8)

    equalized = lookup[img]
    # Interpolar con el original según el slider de intensidad
    result = (img.astype(np.float32) * (1.0 - strength) + equalized.astype(np.float32) * strength)
    return np.clip(result, 0, 255).astype(np.uint8)

def array_to_base64_png(arr: np.ndarray) -> str:
    """Convierte array NumPy 2D a PNG base64 ultraliviano para el DOM."""
    pil_img = Image.fromarray(arr, mode="L")
    buf = io.BytesIO()
    pil_img.save(buf, format="PNG", optimize=True)
    b64 = base64.b64encode(buf.getvalue()).decode("utf-8")
    return f"data:image/png;base64,{b64}"

def render_svg_histogram(img: np.ndarray, color: str = "#10b981") -> str:
    """Genera histograma vectorial SVG de 256 niveles instantáneo sin Matplotlib."""
    hist = np.bincount(img.flatten(), minlength=256)
    max_val = max(1, hist.max())
    norm_hist = (hist / max_val) * 80  # Altura máxima 80px

    svg_paths = []
    for i, h in enumerate(norm_hist):
        y = 80 - h
        svg_paths.append(f'<line x1="{i}" y1="80" x2="{i}" y2="{y:.1f}" stroke="{color}" stroke-width="1"/>')

    svg = f'''
    <svg viewBox="0 0 256 85" width="100%" height="90" style="background:#0b1120; border-radius:8px; padding:4px;">
        {''.join(svg_paths)}
        <line x1="0" y1="82" x2="256" y2="82" stroke="#475569" stroke-width="1"/>
        <text x="2" y="84" font-size="8" fill="#94a3b8">0</text>
        <text x="110" y="84" font-size="8" fill="#94a3b8">128</text>
        <text x="238" y="84" font-size="8" fill="#94a3b8">255</text>
    </svg>
    '''
    return svg

# ==============================================================================
# INTERFAZ SHINY COMPACTA Y MOBILE-FIRST
# ==============================================================================

app_ui = ui.page_fluid(
    ui.tags.head(
        ui.tags.meta(name="viewport", content="width=device-width, initial-scale=1.0, maximum-scale=1.0, user-scalable=no"),
        ui.tags.style("""
            body { background-color: #070b14; color: #f8fafc; font-family: -apple-system, system-ui, sans-serif; margin: 0; padding: 12px; }
            .card { background: #0f172a; border: 1px solid rgba(56, 189, 248, 0.2); border-radius: 14px; padding: 14px; margin-bottom: 12px; box-shadow: 0 10px 25px rgba(0,0,0,0.5); }
            .title-bar { display: flex; justify-content: space-between; align-items: center; margin-bottom: 10px; }
            .img-container { display: flex; flex-direction: column; align-items: center; justify-content: center; width: 100%; }
            .preview-img { width: 100%; max-width: 256px; height: auto; border-radius: 8px; border: 2px solid #38bdf8; box-shadow: 0 0 20px rgba(56, 189, 248, 0.2); }
            .btn-group { display: flex; gap: 8px; width: 100%; margin-top: 6px; }
            .btn-group .btn { flex: 1; font-size: 13px; font-weight: 600; padding: 6px; }
            .challenge-box { background: rgba(16, 185, 129, 0.1); border: 1px solid rgba(16, 185, 129, 0.4); border-radius: 10px; padding: 10px; font-size: 13px; color: #6ee7b7; text-align: center; font-weight: 600; }
        """)
    ),

    # Header Compacto
    ui.div(
        {"class": "title-bar"},
        ui.div(
            ui.tags.span("🔬 LAB VIRTUAL: ", style="color:#10b981; font-weight:800; font-size:16px;"),
            ui.tags.span("Histogramas y Contraste", style="font-weight:700; font-size:16px;")
        ),
        ui.input_action_button("info_btn", "ℹ️ Guía", class_="btn btn-sm btn-outline-info")
    ),

    # Panel Colapsable Teórico
    ui.panel_conditional(
        "input.info_btn % 2 == 1",
        ui.div(
            {"class": "card", "style": "background:#1e293b; border-color:#38bdf8; font-size:13px; line-height:1.4;"},
            ui.tags.b("El Concepto: "),
            "El histograma cuenta cuántos píxeles existen en cada brillo (0 a 255). Si las barras están amontonadas en el medio (niebla) o al inicio (oscuridad), el ojo pierde texturas. ",
            ui.tags.b("Ecualizar "), "estira las frecuencias a lo largo de todo el espectro mediante la función acumulada (CDF)."
        )
    ),

    # Área Visual Principal (Mitad Superior)
    ui.div(
        {"class": "card"},
        ui.div(
            {"class": "img-container"},
            ui.output_ui("display_image"),
            ui.div(
                {"style": "width: 100%; max-width: 256px; margin-top: 10px;"},
                ui.tags.div({"style": "font-size:11px; color:#94a3b8; font-weight:700; margin-bottom:4px;"}, "DISTRIBUCIÓN DE TONOS (HISTOGRAMA):"),
                ui.output_ui("display_histogram")
            )
        )
    ),

    # Controles Interactivos (Mitad Inferior)
    ui.div(
        {"class": "card"},
        ui.input_radio_buttons(
            "view_mode", "Visualizar:",
            {"proc": "✨ Imagen Procesada", "orig": "📷 Imagen Original"},
            inline=True
        ),
        ui.input_select(
            "preset", "Escenario de Entrada:",
            {"fog": "🌫️ Niebla (Bajo Contraste)", "dark": "🌑 Subexpuesta (Oscuridad)", "normal": "☀️ Normal"}
        ),
        ui.input_slider("strength", "Intensidad de Ecualización:", min=0.0, max=1.0, value=1.0, step=0.05),
    ),

    # El Reto Pedagógico Directo
    ui.div(
        {"class": "challenge-box"},
        "🎯 Reto: Con el preset 'Niebla', sube la intensidad al 100% y observa cómo las barras se expanden a los extremos rescatando el patrón circular."
    )
)

# ==============================================================================
# SERVIDOR REACTIVO (ZERO-LATENCY)
# ==============================================================================

def server(input, output, session):

    @reactive.calc
    def current_raw_img():
        return generate_test_image(input.preset())

    @reactive.calc
    def processed_img():
        raw = current_raw_img()
        return equalize_histogram(raw, float(input.strength()))

    @output
    @render.ui
    def display_image():
        img = current_raw_img() if input.view_mode() == "orig" else processed_img()
        b64 = array_to_base64_png(img)
        return ui.HTML(f'<img src="{b64}" class="preview-img" alt="Visualizador de Imagen" />')

    @output
    @render.ui
    def display_histogram():
        img = current_raw_img() if input.view_mode() == "orig" else processed_img()
        color = "#38bdf8" if input.view_mode() == "orig" else "#10b981"
        svg = render_svg_histogram(img, color=color)
        return ui.HTML(svg)

app = App(app_ui, server)
